WITH base AS (SELECT * FROM inventory WHERE product_id IN (5, 7, 8, 9) OR store_id IN (1, 3, 5, 6)), inventory_stats AS (SELECT product_id, store_id, ROUND(AVG(quantity), 2) AS avg_quantity, COUNT(quantity) AS quantity_count FROM base GROUP BY product_id, store_id) SELECT product_id, store_id, avg_quantity FROM inventory_stats WHERE quantity_count > 5 ORDER BY 2 DESC, product_id LIMIT 20;
